InputAuthority(std::uint64_t round, std::uint64_t host, std::uint64_t peer)
    : round_(round), host_(host), peer_(peer) {
    if (round == 0 || host == 0 || peer == 0 || host == peer) {
        throw std::invalid_argument("InputAuthority: invalid round or participants");
    }
}

InputAuthority(const InputAuthority&) = delete;
InputAuthority& operator=(const InputAuthority&) = delete;

const std::uint64_t round_;
const std::uint64_t host_;
const std::uint64_t peer_;
TickInputs inputs_{

InputDecision submit(std::uint64_t authenticated_actor, const Frame& frame) noexcept {
    if (!active_) {
        return InputDecision::inactive;
    }
    if (authenticated_actor == 0) {
        return InputDecision::unauthenticated;
    }

    Side side;
    if (authenticated_actor == host_) {
        side = Side::host;
    } else if (authenticated_actor == peer_) {
        side = Side::peer;
    } else {
        return InputDecision::not_participant;
    }

    if (frame.type != kRoundInputType) {
        return InputDecision::forbidden_type;
    }

    RoundBatch batch{};
    if (!decode_round_input(frame, batch)) {
        return InputDecision::malformed;
    }
    if (batch.round != round_) {
        return InputDecision::wrong_round;
    }

    const Put put = inputs_.put_batch(
        side, batch.inputs.first_tick,
        batch.inputs.masks.data(), batch.inputs.count);
    return map_put(put);
}

// Commit-or-rollback: build the result on a copy, assign only on success.
TickInputs candidate = *this;
bool any_stored = false;
for (std::size_t i = 0; i < count; ++i) {
    const std::uint32_t tick =
        static_cast<std::uint32_t>(static_cast<std::uint64_t>(first) + i);
    const Put result = candidate.put(side, tick, masks[i]);
    if (result == Put::stored) {
        any_stored = true;
    } else if (result != Put::duplicate) {
        return result; // Whole batch rejected; *this is unchanged.
    }
}
*this = candidate;
return any_stored ? Put::stored : Put::duplicate;

bool take(std::uint8_t& host, std::uint8_t& peer) noexcept {
    if (!active_) {
        return false;
    }
    if (&host == &peer) {
        return false;
    }

    std::uint8_t host_value = 0;
    std::uint8_t peer_value = 0;
    if (!inputs_.peek(host_value, peer_value)) {
        return false;
    }
    if (!inputs_.consume()) {
        return false;
    }

    host = host_value;
    peer = peer_value;
    return true;
}

bool start() noexcept {
    if (active_ || ended_) {
        return false;
    }
    active_ = true;
    return true;
}

// Permanently deactivates the authority. Idempotent and final.
void close() noexcept {
    active_ = false;
    ended_ = true;
}

InputAuthority& authority_;
const std::uint64_t actor_;
FrameParser parser_;
bool failed_ = false;

bool feed(const std::uint8_t* bytes, std::size_t count, Report& report) noexcept {
    report = {};
    if (failed_) return false;
    if (count > 16 || (count && !bytes) || !parser_.append(bytes, count)) {
        failed_ = true;
        return false;
    }
    for (;;) {
        Frame frame;
        const auto parsed = parser_.next(frame);
        if (parsed == ParseStatus::need_more) return true;
        if (parsed == ParseStatus::error) { failed_ = true; return false; }
        ++report.handled;
        report.last = authority_.submit(actor_, frame);
        if (report.last == InputDecision::stored) ++report.stored;
        else if (report.last == InputDecision::duplicate) ++report.duplicates;
        else ++report.denied;
    }
}

